mapper.select:
SELECT id, id_site AS idSite, alert_type AS alertType, weather_parameter AS weatherParameter, warning_operator AS warningOperator, warning_threshold AS warningThreshold, critical_operator AS criticalOperator, critical_threshold AS criticalThreshold, unit FROM weather_alert_configuration WHERE
id_site = #{value}
id_site IS NULL

mapper.update:
UPDATE weather_alert
SET enabled = FALSE
WHERE id_site = #{idSite}
AND id_alert_configuration = #{idAlertConfiguration}

mapper.select:
SELECT wa.id, wa.id_site AS idSite, wa.id_alert_configuration AS idAlertConfiguration, wa.weather_event AS weatherEvent, wa.reading, wa.severity, CASE wa.severity WHEN 1 THEN wac.critical_threshold ELSE wac.warning_threshold END AS threshold, CASE wa.severity WHEN 1 THEN wac.critical_operator ELSE wac.warning_operator END AS operator, wa.unit, wa.forecast_date AS forecastDate, wa.enabled, wac.alert_type AS alertType, s.name AS siteName FROM weather_alert wa JOIN weather_alert_configuration wac ON wa.id_alert_configuration = wac.id JOIN site s ON s.id = wa.id_site WHERE wa.id_site IN
#{id}
AND wa.enabled = true
AND s.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY s.name LIMIT #{limit} OFFSET #{offset}
